function sommeTableau(arr) {
  return arr.reduce((acc, num) => acc + num, 0);
}

function doublerPairs(arr) {
  return arr.filter(n => n % 2 === 0).map(n => n * 2);
}

function compterOccurrences(arr) {
  return arr.reduce((acc, val) => {
    acc[val] = (acc[val] || 0) + 1;
    return acc;
  }, {});
}

function utilisateursBonScores(utilisateurs) {
  return utilisateurs
    .filter(u => u.score > 80)
    .sort((a, b) => b.score - a.score);
}

function entriesObjet(obj) {
  const result = [];
  for (let key in obj) {
    result.push([key, obj[key]]);
  }
  return result;
}
